<?php get_header(); while (have_posts()): the_post(); $id=get_the_ID(); $images=mgt_images($id); $site=mgt_contacts(); $terms=get_the_terms($id,'mgt_category'); $term=$terms&&!is_wp_error($terms)?$terms[0]:null; $name=mgt_name($id); ?>
<main id="main" class="catalog-main"><div class="shell catalog-content"><a class="back-catalog" href="<?php echo esc_url(mgt_url('/products/')); ?>"><?php echo esc_html(mgt_text('همه محصولات →','← All products')); ?></a><div class="product-detail"><div><div class="detail-image">
<?php foreach ($images as $i=>$src): ?><img class="product-gallery-image" src="<?php echo esc_url($src); ?>" alt="<?php echo esc_attr($name); ?>" <?php echo $i>0?'hidden loading="lazy"':''; ?>><?php endforeach; ?>
</div><?php if (count($images)>1): ?><div class="product-thumbnails"><?php foreach ($images as $i=>$src): ?><button type="button" class="<?php echo $i===0?'selected':''; ?>" data-gallery="<?php echo esc_attr($i); ?>" aria-label="<?php echo esc_attr(mgt_text('تصویر ','Image ').($i+1)); ?>" aria-pressed="<?php echo $i===0?'true':'false'; ?>"><img src="<?php echo esc_url($src); ?>" alt=""></button><?php endforeach; ?></div><?php endif; ?></div>
<div class="detail-copy"><span class="section-kicker"><?php echo esc_html($term?mgt_category_name($term):'MGT'); ?></span><h1><?php echo esc_html($name); ?></h1><?php if (mgt_meta($id,'sku')): ?><p><?php echo esc_html(mgt_text('شماره قطعه','Part number')); ?>: <bdi><?php echo esc_html(mgt_meta($id,'sku')); ?></bdi></p><?php endif; ?><p class="multiline"><?php echo esc_html(mgt_meta($id,mgt_en()?'descriptionEn':'descriptionFa')); ?></p><a class="gold-button" href="<?php echo esc_url('mailto:'.$site['companyEmail'].'?subject='.rawurlencode('Product enquiry: '.(mgt_meta($id,'nameEn')?:$name).' '.mgt_meta($id,'sku'))); ?>"><?php echo esc_html(mgt_text('استعلام این محصول','Enquire about this product')); ?></a><a class="detail-phone" href="<?php echo esc_url('tel:'.$site['officePhone']); ?>"><?php echo esc_html(mgt_text('تماس با شرکت','Call our team')); ?> <bdi><?php echo esc_html($site['officePhone']); ?></bdi></a></div></div>
<?php $specs=mgt_meta($id,mgt_en()?'specsEn':'specsFa'); if ($specs): ?><section class="product-specs"><h2><?php echo esc_html(mgt_text('مشخصات محصول','Specifications')); ?></h2><p class="multiline"><?php echo esc_html($specs); ?></p></section><?php endif; ?></div></main>
<?php endwhile; get_footer(); ?>
